-- PostgreSQL 15+; applied manually with psql, never against a production database without backup.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),handle varchar(40) NOT NULL UNIQUE,email varchar(254) NOT NULL UNIQUE,password_hash text NOT NULL,disabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id varchar(64) PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS member_profiles(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,bio varchar(500) NOT NULL DEFAULT '',city varchar(100) NOT NULL DEFAULT 'Rennes',kind varchar(20) NOT NULL DEFAULT 'buyer' CHECK(kind IN ('buyer','reseller','care')),approved boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS follows(follower_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,followed_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,followed_id),CHECK(follower_id<>followed_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS participants(conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id),body varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requester_id uuid NOT NULL REFERENCES users(id),provider_id uuid NOT NULL REFERENCES users(id),starts_at timestamptz NOT NULL,note varchar(500) NOT NULL DEFAULT '',status varchar(20) NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','declined','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(requester_id<>provider_id));
CREATE INDEX IF NOT EXISTS idx_appointments_provider ON appointments(provider_id,starts_at);
CREATE TABLE IF NOT EXISTS verified_interactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES users(id),seller_id uuid NOT NULL REFERENCES users(id),kind varchar(20) NOT NULL CHECK(kind IN ('sale','service')),completed_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),interaction_id uuid NOT NULL UNIQUE REFERENCES verified_interactions(id),author_id uuid NOT NULL REFERENCES users(id),subject_id uuid NOT NULL REFERENCES users(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body varchar(1200) NOT NULL,visibility varchar(20) NOT NULL DEFAULT 'pending' CHECK(visibility IN ('pending','published','rejected')),created_at timestamptz NOT NULL DEFAULT now());
